INSERT INTO events (title, start_time, end_time, location_text, category, description)
SELECT s.title, s.start_time, s.end_time, s.location_text, s.category, s.description
FROM seed_events s
WHERE NOT EXISTS (
  SELECT 1
  FROM events e
  WHERE e.title = s.title
    AND e.start_time = s.start_time
    AND e.location_text IS NOT DISTINCT FROM s.location_text
);
